// Country-wide public inventories. No interpolation or guessed route association.
import {parsePK,roadKey} from './core.js?v=1.2.0';
export const FR='https://data.geopf.fr/wfs/ows';
export const ES='https://api-features.idee.es/collections/markerpost/items';
export const ES_ROADS='https://servicios.idee.es/wfs-inspire/transportes';
export const DE='https://services2.arcgis.com/jUpNdisbWqRpMo35/arcgis/rest/services/KmBAB/FeatureServer/0';
const day=()=>new Date().toISOString().slice(0,10);
const xml=s=>String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
const decode=s=>s.replace(/&(?:amp|lt|gt|quot|apos);/g,x=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'"}[x]));
export function roadNames(text){
 if(/ExceptionReport/.test(text))throw new Error('Le catalogue routier IGN Espagne ne répond pas à cette demande.');
 const out={};for(const m of text.matchAll(/<(?:[\w-]+:)?Road\b[^>]*gml:id="([^"]+)"[^>]*>([\s\S]*?)<\/(?:[\w-]+:)?Road>/g)){
  const name=m[2].match(/<(?:[\w-]+:)?text>([^<]+)<\/(?:[\w-]+:)?text>/)?.[1];
  const id=m[2].match(/<(?:[\w-]+:)?localId>([^<]+)<\/(?:[\w-]+:)?localId>/)?.[1]||m[1].replace(/^TN-RO_ROAD_/,'');
  if(name)out[m[1]]={name:decode(name),id};
 }return out;
}
export function frRecords(j){return (j.features||[]).flatMap(f=>{const p=f.properties||{},xy=f.geometry?.coordinates,value=parsePK(p.numero);if(!['PR valide','PR0 valide'].includes(p.statut)||!/^\d+(?:[.,]\d+)?$/.test(String(p.numero))||!Number.isFinite(value)||!xy||!p.route)return[];return [{id:'ign-fr:'+p.cleabs,country:'FR',road:p.route,value,unit:'PR',lon:xy[0],lat:xy[1],direction:'Côté '+(p.cote||'inconnu'),section:p.identifiant_de_section,source:'IGN France · BD TOPO · '+(p.sources||''),status:p.statut,kind:'PR officiel valide — lié à une section et à un côté',sourceUpdated:p.date_modification||p.date_creation,retrieved:day(),url:FR+'?'+new URLSearchParams({service:'WFS',version:'2.0.0',request:'GetFeature',typeNames:'BDTOPO_V3:point_de_repere',outputFormat:'application/json',resourceID:f.id})}];})}
export function esRecords(j,names={}){return (j.features||[]).flatMap(f=>{const p=f.properties||{},xy=f.geometry?.coordinates;if(!f.id?.startsWith('VIAL_PK')||!xy||typeof p.numero!=='number')return[];const n=names[p.href_vial?.replace(/^#/,'')];return[{id:'ign-es:'+f.id,country:'ES',road:n?.name||'Route non renseignée',roadUnknown:!n,roadRef:p.href_vial?.replace(/^#/,''),value:p.numero,unit:'PK',lon:xy[0],lat:xy[1],direction:({bothDirections:'Les deux sens',inDirection:'Sens de référence',inOppositeDirection:'Sens opposé'})[p.sentidopk?.split('/').pop()]||'Sens inconnu',section:p.localid_vial,source:'IGN / CNIG Espagne · IGR-RT · CC-BY 4.0',status:'Borne officielle référencée'+(!n?' · route non résolue':''),kind:'Borne du référentiel officiel ; présence de la personne non vérifiée',sourceUpdated:p.fecha_alta,retrieved:day(),url:ES+'/'+f.id+'?f=json'}]})}
export function deRecords(j){return(j.features||[]).flatMap(f=>{const p=f.attributes||{},g=f.geometry;if(!g||!p.Bez||typeof p.Kilometer!=='number')return[];return[{id:'bkg-de:'+p.OBJECTID,country:'DE',road:p.Bez,value:p.Kilometer,unit:'PK',lat:g.y,lon:g.x,direction:'Sens de kilométrage : '+(p.Richtung||'inconnu')+' (ne précise pas le sens de circulation)',source:'© Bundesamt für Kartographie und Geodäsie (2025) · POI-Open · diffusion Esri Deutschland',status:'Kilométrage du référentiel BKG, millésime 03/2025',kind:'Position du kilométrage BKG — précision du référentiel',sourceUpdated:'2025-03',retrieved:day(),url:DE+'/'+p.OBJECTID+'?f=pjson'}]})}
export function countriesInBounds([s,w,n,e]){const ranges={ES:[[27,-18.5,44.1,4.5]],FR:[[41,-5.6,51.5,10],[2,-55,6,-51],[14,-62,17,-60],[-22,55,-20,56],[-14,44,-12,46]],DE:[[47.2,5.8,55.1,15.2]]};return Object.keys(ranges).filter(c=>ranges[c].some(([a,b,d,f])=>s<=d&&n>=a&&w<=f&&e>=b))}
export function frURL({bbox,road,start=0}){const p={service:'WFS',version:'2.0.0',request:'GetFeature',typeNames:'BDTOPO_V3:point_de_repere',outputFormat:'application/json',srsName:'EPSG:4326',count:2000,startIndex:start};if(bbox)p.bbox=bbox.join(',')+',urn:ogc:def:crs:EPSG::4326';if(road)p.CQL_FILTER="route='"+road.replace(/'/g,"''")+"'";return FR+'?'+new URLSearchParams(p)}
export function createNationalLoader(getJSON,getText,onData=()=>{}){
 const cache=new Map(),names={};
 function cached(key,task){if(!cache.has(key)){const p=task().catch(e=>{cache.delete(key);throw e});cache.set(key,p)}return cache.get(key)}
 async function french(args){let pks=[],total=0;for(let start=0;start<16000;start+=2000){const j=await getJSON(frURL({...args,start}));if(!Array.isArray(j.features))throw new Error('Réponse IGN France invalide.');total=+(j.numberMatched??j.totalFeatures);pks.push(...frRecords(j));if(j.features.length<2000||start+j.features.length>=total)return {pks,complete:true}}return {pks,complete:false}}
 async function german({bbox,road}){let pks=[];const where=road?"Bez='"+roadKey(road).toUpperCase()+"'":'1=1';for(let offset=0;offset<20000;offset+=2000){const q={f:'json',where,outFields:'*',outSR:'4326',resultOffset:offset,resultRecordCount:2000,orderByFields:'OBJECTID'};if(bbox){q.geometry=[bbox[1],bbox[0],bbox[3],bbox[2]].join(',');q.geometryType='esriGeometryEnvelope';q.inSR='4326';q.spatialRel='esriSpatialRelIntersects'}const j=await getJSON(DE+'/query?'+new URLSearchParams(q));if(j.error||!Array.isArray(j.features))throw new Error(j.error?.message||'Réponse BKG invalide.');pks.push(...deRecords(j));if(!j.exceededTransferLimit)return {pks,complete:true}}return{pks,complete:false}}
 async function namesByIds(ids){const missing=[...new Set(ids)].filter(id=>id&&!names[id]);for(let i=0;i<missing.length;i+=20){const part=missing.slice(i,i+20);const text=await getText(ES_ROADS+'?'+new URLSearchParams({service:'WFS',version:'2.0.0',request:'GetFeature',typeNames:'Road',resourceID:part.join(','),count:part.length}));Object.assign(names,roadNames(text))}}
 async function spanish({bbox,road}){let localIds=[null],complete=true,warning='';if(road&&Object.values(names).some(n=>roadKey(n.name)===roadKey(road))){localIds=[...new Set(Object.values(names).filter(n=>roadKey(n.name)===roadKey(road)).map(n=>n.id))]}else if(road){const path='tn:geographicalName/gn:GeographicalName/gn:spelling/gn:SpellingOfName/gn:text';const filter=`<Filter xmlns="http://www.opengis.net/fes/2.0" xmlns:tn="http://inspire.ec.europa.eu/schemas/tn/4.0" xmlns:gn="http://inspire.ec.europa.eu/schemas/gn/4.0"><PropertyIsEqualTo><ValueReference>${path}</ValueReference><Literal>${xml(road.trim().toUpperCase())}</Literal></PropertyIsEqualTo></Filter>`;const text=await getText(ES_ROADS+'?'+new URLSearchParams({service:'WFS',version:'2.0.0',request:'GetFeature',typeNames:'Road',filter,count:20}));const found=roadNames(text);Object.assign(names,found);localIds=[...new Set(Object.values(found).map(v=>v.id).filter(Boolean))];if(/numberReturned="20"/.test(text))complete=false;if(!localIds.length)return{pks:[],complete,warning:'Route non retrouvée dans le catalogue national IGN Espagne.'}}
 const features=[];for(const id of localIds){for(let offset=0;offset<16000;offset+=1000){const q={f:'json',limit:1000,offset};if(bbox)q.bbox=[bbox[1],bbox[0],bbox[3],bbox[2]].join(',');if(id)q.localid_vial=id;const j=await getJSON(ES+'?'+new URLSearchParams(q));if(!Array.isArray(j.features))throw new Error('Réponse IGN Espagne invalide.');features.push(...j.features);onData({pks:esRecords(j,names)});if(!j.links?.some(l=>l.rel==='next'))break;if(offset===15000)complete=false}}
 if(!road&&features.some(f=>f.id?.startsWith('VIAL_PK')&&!names[f.properties.href_vial?.replace(/^#/, '')]))warning='Certains noms de routes restent à résoudre : sélectionnez une borne pour consulter sa route.';
 return{pks:esRecords({features},names),complete,warning};}
 async function load(country,args){return cached(country+JSON.stringify(args),async()=>{const result=await({FR:french,ES:spanish,DE:german}[country])(args);return{...result,country}})}
 return{setNames:value=>Object.assign(names,value),resolve:async p=>{if(!p.roadRef)return p;await namesByIds([p.roadRef]);return names[p.roadRef]?{...p,road:names[p.roadRef].name,roadUnknown:false,status:'Borne officielle référencée'}:p},bounds:(country,bbox)=>load(country,{bbox}),road:(country,road)=>load(country,{road:country==='FR'?roadKey(road).toUpperCase():country==='ES'?road.trim().toUpperCase().replace(/^([A-Z]{1,3})\s*-?\s*(\d+[A-Z]?)$/,'$1-$2'):road.trim().toUpperCase()})};
}
